/// Persistent, session-scoped state previously stored directly on `Session`.
pub(crate) struct SessionState {
    pub(crate) session_configuration: SessionConfiguration,
    pub(crate) history: ContextManager,
    pub(crate) latest_rate_limits: Option<RateLimitSnapshot>,
    pub(crate) server_reasoning_included: bool,
    pub(crate) mcp_dependency_prompted: HashSet<String>,
    pub(crate) additional_context: AdditionalContextStore,
    /// Settings used by the latest regular user turn, used for turn-to-turn
    /// model/realtime handling on subsequent regular turns (including full-context
    /// reinjection after resume or `/compact`).
    previous_turn_settings: Option<PreviousTurnSettings>,
    /// Runtime accounting state for the active auto-compaction window.
    auto_compact_window: AutoCompactWindow,
    /// Startup prewarmed session prepared during session initialization.
    pub(crate) startup_prewarm: Option<SessionStartupPrewarmHandle>,
    pub(crate) current_time_reminder: CurrentTimeReminderState,
    pub(crate) pending_session_start_sources: VecDeque<codex_hooks::SessionStartSource>,
    granted_permissions_by_environment_id: HashMap<String, AdditionalPermissionProfile>,
    /// Layer 2 context pruning: tool-call ids already covered by an agent-authored
    /// prune record, so a later pass never re-litigates them. See
    /// `crate::session::context_prune`.
    pub(crate) context_prune_covered: HashSet<String>,
    /// Cumulative estimated tokens reclaimed by applied context-pruning passes.
    pub(crate) context_prune_saved_tokens: u64,
    /// Failed pruning passes since the last applied one. A failed pass covers
    /// nothing, so the next turn rebuilds the identical batch; this drives the
    /// backoff that stops one bad batch from retrying on every turn forever.
    pub(crate) context_prune_consecutive_failures: u32,
    /// Earliest instant an automatic pruning pass may run again. `/prune` ignores it.
    pub(crate) context_prune_retry_after: Option<Instant>,
    /// Hysteresis gate for automatic pruning: which phase of the 30% -> 20% -> regrow
    /// cycle the session is in. See `crate::context_pruner::PruneCycle`.
    pub(crate) context_prune_cycle: crate::context_pruner::PruneCycle,
}

impl SessionState {
    /// Create a new session state mirroring previous `State::default()` semantics.
    #[cfg(test)]
    pub(crate) fn new(session_configuration: SessionConfiguration) -> Self {
        Self::new_with_auto_compact_window_ids(
            session_configuration,
            AutoCompactWindowIds::new_initial(),
        )
    }

    pub(crate) fn new_with_auto_compact_window_ids(
        session_configuration: SessionConfiguration,
        auto_compact_window_ids: AutoCompactWindowIds,
    ) -> Self {
        let history = ContextManager::new();
        Self {
            session_configuration,
            history,
            latest_rate_limits: None,
            server_reasoning_included: false,
            mcp_dependency_prompted: HashSet::new(),
            additional_context: AdditionalContextStore::default(),
            previous_turn_settings: None,
            auto_compact_window: AutoCompactWindow::new_with_ids(auto_compact_window_ids),
            startup_prewarm: None,
            current_time_reminder: CurrentTimeReminderState::default(),
            pending_session_start_sources: VecDeque::new(),
            granted_permissions_by_environment_id: HashMap::new(),
            context_prune_covered: HashSet::new(),
            context_prune_saved_tokens: 0,
            context_prune_consecutive_failures: 0,
            context_prune_retry_after: None,
            context_prune_cycle: crate::context_pruner::PruneCycle::default(),
        }
    }

    /// True when automatic pruning is still inside the backoff left by a failed pass.
    pub(crate) fn context_prune_backoff_active(&self) -> bool {
        self.context_prune_retry_after
            .is_some_and(|retry_after| Instant::now() < retry_after)
    }

    pub(crate) fn record_context_prune_failure(&mut self) -> u32 {
        self.context_prune_consecutive_failures =
            self.context_prune_consecutive_failures.saturating_add(1);
        let delay = crate::context_pruner::retry_delay_after_failures(
            self.context_prune_consecutive_failures,
        );
        self.context_prune_retry_after = Some(Instant::now() + delay);
        self.context_prune_consecutive_failures
    }

    pub(crate) fn clear_context_prune_failures(&mut self) {
        self.context_prune_consecutive_failures = 0;
        self.context_prune_retry_after = None;
    }

    /// Feeds the latest measurement into the pruning hysteresis gate and reports whether
    /// an automatic pass may run. A cooling cycle re-arms here, and only here, once use
    /// has climbed back to the pressure trigger.
    pub(crate) fn observe_context_prune_usage(
        &mut self,
        used_tokens: i64,
        context_window: i64,
    ) -> bool {
        self.context_prune_cycle
            .observe(used_tokens, context_window);
        self.context_prune_cycle.may_run()
    }

    pub(crate) fn record_context_prune_pass(&mut self) {
        self.context_prune_cycle.record_pass();
    }

    /// Closes the running cycle: the target was reached, the budget is spent, or nothing
    /// is left to reclaim. Blocks every further automatic pass until regrowth.
    pub(crate) fn close_context_prune_cycle(&mut self) {
        self.context_prune_cycle.close();
    }

    /// True when the closed cycle gave up while still in pressure, so pruning alone
    /// cannot buy this session the headroom it needs.
    pub(crate) fn context_prune_cycle_stalled(&self) -> bool {
        self.context_prune_cycle.stalled_in_pressure()
    }

    // History helpers
    pub(crate) fn record_items<I>(&mut self, items: I, policy: TruncationPolicy)
    where
        I: IntoIterator,
        I::Item: std::ops::Deref<Target = ResponseItem>,
    {
        self.history.record_items(items, policy);
    }

    pub(crate) fn previous_turn_settings(&self) -> Option<PreviousTurnSettings> {
        self.previous_turn_settings.clone()
    }
    pub(crate) fn set_previous_turn_settings(
        &mut self,
        previous_turn_settings: Option<PreviousTurnSettings>,
    ) {
        self.previous_turn_settings = previous_turn_settings;
    }

    pub(crate) fn clone_history(&self) -> ContextManager {
        self.history.clone()
    }

    pub(crate) fn replace_history(
        &mut self,
        items: Vec<ResponseItem>,
        reference_context_item: Option<TurnContextItem>,
    ) {
        self.history.replace(items);
        self.history
            .set_reference_context_item(reference_context_item);
        self.auto_compact_window.clear_prefill();
    }

    pub(crate) fn set_token_info(&mut self, info: Option<TokenUsageInfo>) {
        self.history.set_token_info(info);
    }

    pub(crate) fn set_reference_context_item(&mut self, item: Option<TurnContextItem>) {
        self.history.set_reference_context_item(item);
    }

