fn estimate_tokens(path: &Path, bytes: u64, max_chars: usize) -> u64 {
    std::fs::read_to_string(path).map_or_else(
        |_| bytes.min(max_chars as u64).div_ceil(4),
        |content| (content.trim().chars().count().min(max_chars) as u64).div_ceil(4),
    )
}

